from math import gcd

def order(a, n):                       # smallest r > 0 with a**r = 1 (mod n): the step a quantum computer speeds up
    r, value = 1, a % n
    while value != 1:
        value, r = value * a % n, r + 1
    return r

def factors_from_order(n, a):
    if gcd(a, n) != 1:
        return gcd(a, n), n // gcd(a, n)                   # lucky guess: a already shares a factor with n
    r = order(a, n)
    if r % 2:
        return None                                        # odd period: try another a
    x = pow(a, r // 2, n)
    if x == n - 1:
        return None                                        # a**(r/2) = -1: try another a
    return gcd(x - 1, n), gcd(x + 1, n)

for n, a in ((15, 7), (21, 2), (3233, 3), (3233, 5)):
    print(f"N={n:<5} a={a}: order={order(a, n):<4} factors={factors_from_order(n, a)}")

from math import gcd

def steps_to_find_order(a, n):
    steps, value = 1, a % n
    while value != 1:
        value, steps = value * a % n, steps + 1
    return steps

for p, q in ((11, 13), (101, 103), (1009, 1013)):
    n = p * q
    worst = max(steps_to_find_order(a, n) for a in range(2, 41) if gcd(a, n) == 1)
    print(f"N = {p} x {q} = {n:>9,}   largest brute-force order search among a = 2..40: {worst:>8,} steps")

