ASSETS = [   # (asset, needs confidentiality for years, protected by classical public-key exchange, long-lived signature)
    ("web session cookies", 0.01, True, False),
    ("customer database backups in transit", 10, True, False),
    ("VPN traffic of a research lab", 25, True, False),
    ("firmware update signing root", 0, False, True),
    ("AES-256 encrypted archive (key stored locally)", 30, False, False),
]
for name, shelf_life_years, classical_exchange, long_lived_signature in ASSETS:
    if classical_exchange and shelf_life_years >= 5:
        verdict = "HNDL risk: migrate key exchange first"
    elif classical_exchange:
        verdict = "HNDL applies but the data loses value quickly"
    elif long_lived_signature:
        verdict = "not HNDL: signature trust must outlast a break"
    else:
        verdict = "not exposed through public-key exchange"
    print(f"{name:48} {verdict}")
